mat2 rot(float a) {
  float ca=cos(a);
  float sa=sin(a);
  return mat2(ca,sa,-sa,ca);
}



float cylcap( vec3 p, float h, float r )
{
  vec2 d = abs(vec2(length(p.xz),p.y)) - vec2(h,r);
  return min(max(d.x,d.y),0.0) + length(max(d,0.0));
}


float hash11(float t) {
  return fract( sin(t * 7361.994) * 4518.442);
}

vec3 lattice (float t ) {



  float m = t;
  float mx = floor((m-2.)/3.);
  float my = floor((m-1.)/3.);
  float mz = floor((m-0.)/3.);

  float n= m+1.;
  float nx = floor((n-2.)/3.);
  float ny = floor((n-1.)/3.);
  float nz = floor((n-0.)/3.);


  vec3 a =  
  mix(
      vec3(
          hash11(mx)-.5,
          hash11(my)-.5,
          hash11(mz)-.5
      ),
      vec3(
          hash11(nx)-.5,
          hash11(ny)-.5,
          hash11(nz)-.5
      ) , 
      fract(t)
  );
  return a;
}



float hash31(vec3 p3)
{
	p3  = fract(p3 * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}
float hash21(vec2 p2)
{
	p2  = fract(p2 * .1031);
    p2 += dot(p2, p2.xy + 33.33);
    return fract((p2.x + p2.y));
}

float closestWall(vec3 p) {
    vec3 d = min(fract(p), 1.0 - fract(p));
    return min(min(d.x, d.y), d.z);
}

float box (vec3 p, vec3 s) {
    vec3 ap = abs(p) - s;
    return length(max(vec3(0.),ap)) + min( 0., max(ap.x,max(ap.y,ap.z)));


}
float hash( vec2 p )
{
	float h = dot(p,vec2(127.1,311.7));
    return -1.0 + 2.0*fract(sin(h)*43758.5453123);
}
float noise(vec3 p) {
  vec3 ip=floor(p);
  p=fract(p);
  p=smoothstep(0.0,1.0,p);
  vec3 st=vec3(7,37,289);
  vec4 pos=dot(ip,st) + vec4(0,st.y,st.z,st.y+st.z);
  vec4 val=mix(fract(sin(pos)*7894.552), fract(sin(pos+st.x)*7894.552), p.x);
  vec2 val2=mix(val.xz,val.yw, p.y);
  return mix(val2.x,val2.y, p.z);
}

float fbm( vec2 a)
{
    vec3 p = vec3(a,1.);
    float f = 0.0;
    f += 0.5000*noise( p ); p = p*2.02;
    f += 0.2500*noise( p ); p = p*2.03;
    f += 0.1250*noise( p ); p = p*2.01;

    return f;
}
float sph (vec3 p, float n) {
    return length(p) -n ;
}
float field (vec3 p, float scale) {


   float tt = iTime * .1;
   scale *= .25;
   p *= scale;
   vec3 id = floor(p)-.5; 
   p = fract(p) -.5;

   float f1 = hash31(id);


   float ball = box(p, pow(f1,sin(tt*.5)*.5+.5) * vec3(.49));
   // important detail
   float bound = closestWall(p+.5);

   return min(bound + .1, ball)/scale;
}

float map (vec3 p){
    p.xz *= rot(iTime*.1);

    float thing = box(p, vec3(3));

   // geo

    for (float i = 0.; i < 4.; i++) {
       thing = max(thing, -field(p,pow(2.,i)));
    }

    return thing;
}
vec3 norm(vec3 p) {
  vec2 off=vec2(0.001,0.0);
  return normalize(map(p)-vec3(map(p-off.xyy), map(p-off.yxy), map(p-off.yyx))+0.000001);
}

float tick(float t){
    float i = floor(t);
    float f = fract(t);
    f = smoothstep(0.,1.,f);
    return i + f;
}

float getao(vec3 p, vec3 n, float dist) {
  return clamp(map(p+n*dist)/dist,0.0,1.0);
}
float path (float t) {
    float a = sin(sin(t) + .3 * t);
    return a;

}
float pathfbm(float t) {
    float a = 0.;

    a += path( (t+0. ) );
    a += path( (t+21.)*2.)/2.1;
    a += path( (t+211.)*5.)/5.1;

    return a/2.;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

  vec2 uv = vec2(fragCoord.x / iResolution.x, fragCoord.y / iResolution.y);
  uv -= 0.5;
  uv /= vec2(iResolution.y / iResolution.x, 1);

  // nav

  vec3 s = vec3 (0,0,-4);
  s *= (sin(iTime*.3)*.5+.5)+.2;
  vec3 t = vec3(0);

  float tt = iTime * .3;
  s.xz *= rot(tt*.4);
  s.xy *= rot(tt*.5);
  s.zy *= rot(tt*.7);


  vec3 cz=normalize(t-s);
  vec3 cx=normalize(cross(cz,vec3(0,1,0)));
  vec3 cy=-normalize(cross(cz,cx));

  vec3 r=normalize(cx*uv.x+cy*uv.y+cz);



  vec3 col = vec3(0);

  vec3 p = s;

  float dd = 0.;

  float side=sign(map(p));

  for(int i = 0; i < 400; i++) {

      float d=map(p)*side;

      if(d<0.001) {
          vec3 n = norm(p)*side;
          vec3 l = normalize(vec3(-1));

          if ( dot(n,l) < 0.) {
              //l = -l;
          }
          vec3 h = normalize(l-r);

          float diff = max(0., dot(n,l));
          float spec =( 0.4 + pow(max(0., dot(n,h)),100.));

          vec3 remaining = vec3(1) - col;
         // col += pow(remaining * diff *  spec, vec3(2.));
          col += remaining  *  spec * .2;

          side = -side;

          d = .1;

      }
      if ( dd > 10.) {
          break;
      }

      dd += d;
      p+=r*d;
  }



  fragColor = vec4(col, 1);
}
